// AuthServiceServer is the server API for AuthService service.
// All implementations should embed UnimplementedAuthServiceServer
// for forward compatibility.
type AuthServiceServer interface {
	// Service-level tag would cascade to SignIn / SignUp too, but
	// each turnkey has its own opt-in feature tag — the service is
	// untagged here so every rpc carries an explicit method-level
	// tag. Authenticate → `authenticate_turnkey`, SignIn →
	// `sign_in_turnkey`, SignUp → `sign_up_turnkey`.
	Authenticate(context.Context, *AuthReq) (*AuthResp, error)
	SignIn(context.Context, *SignInReq) (*SignInResp, error)
	SignUp(context.Context, *SignUpReq) (*SignUpResp, error)
	// WhoAmI — verify the current bearer + return the principal.
	// Authenticated like any non-excluded endpoint; the body is
	// empty because the principal arrives via the gateway's
	// x-w17-scope-user_id metadata threading.
	WhoAmI(context.Context, *WhoAmIReq) (*WhoAmIResp, error)
	// Logout — revoke the caller's CURRENT session token (base-tier, no
	// `devices` feature). Reads user_id + session_token_id from the gateway
	// auth envelope and deletes that one SESSION token via
	// AuthMutation.DeleteSessionToken. Idempotent.
	Logout(context.Context, *LogoutReq) (*LogoutResp, error)
	// CreateApiToken — issue an API/MCP token for the caller (bearer-
	// authenticated), optionally narrowed to a permission subset. Returns
	// the opaque token ONCE. Gated api_token.
	CreateApiToken(context.Context, *CreateApiTokenReq) (*CreateApiTokenResp, error)
	// CreateBot — provision a machine account AND give it its role, in one
	// call. Gated service_account.
	CreateBot(context.Context, *CreateBotReq) (*CreateBotResp, error)
	// ListBots — the machine accounts. Gated service_account.
	ListBots(context.Context, *ListBotsReq) (*ListBotsResp, error)
	// ListBotRoles — the roles a bot may hold: API-realm roles ONLY.
	//
	// Server-side, not a filtered dropdown. A session-realm role granted to a
	// bot is unreachable anyway — permissions resolve within the presented
	// token's realm — so offering one would mint a credential that silently
	// does nothing. Gated service_account.
	ListBotRoles(context.Context, *ListBotRolesReq) (*ListBotRolesResp, error)
	// IssueBotToken — mint an API token FOR a machine account. Refuses any
	// target that is not `kind = BOT`. Gated service_account.
	IssueBotToken(context.Context, *IssueBotTokenReq) (*IssueBotTokenResp, error)
	// ListApiTokens — the caller's API tokens (management view, no secret).
	ListApiTokens(context.Context, *ListApiTokensReq) (*ListApiTokensResp, error)
	// RevokeApiToken — delete the caller's own API token + its subset rows.
	RevokeApiToken(context.Context, *RevokeApiTokenReq) (*RevokeApiTokenResp, error)
	// ── oauth — authorize-redirect + callback ───────────────────
	// OAuthAuthorizeURL builds the IdP authorize URL (client redirects);
	// OAuthCallback exchanges the code, find-or-creates the user, and issues
	// a session. Both unauthenticated. Gated oauth.
	OAuthAuthorizeURL(context.Context, *OAuthAuthorizeURLReq) (*OAuthAuthorizeURLResp, error)
	OAuthCallback(context.Context, *OAuthCallbackReq) (*OAuthCallbackResp, error)
	// ── two_factor — enrollment + challenge verification ────────
	// EnrollTotp / ConfirmTotp / DisableTotp / GetMfaStatus ride the bearer
	// middleware (manage your own factor). VerifyMfa is unauthenticated
	// (challenge_id stands in for the not-yet-issued token). All gated
	// two_factor.
	EnrollTotp(context.Context, *EnrollTotpReq) (*EnrollTotpResp, error)
	ConfirmTotp(context.Context, *ConfirmTotpReq) (*ConfirmTotpResp, error)
	DisableTotp(context.Context, *DisableTotpReq) (*DisableTotpResp, error)
	GetMfaStatus(context.Context, *GetMfaStatusReq) (*GetMfaStatusResp, error)
	VerifyMfa(context.Context, *VerifyMfaReq) (*VerifyMfaResp, error)
	// ── devices management — list + log out one/others/all ──────
	// ListDevices — the caller's devices (mgmt view, derived trusted /
	// current). RevokeDevice — log out one device (delete its tokens +
	// the Device row). RevokeOtherDevices — log out every device but the
	// caller's. RevokeAllDevices — log out everywhere (incl. caller).
	// All gated `devices`.
	ListDevices(context.Context, *ListDevicesReq) (*ListDevicesResp, error)
	RevokeDevice(context.Context, *RevokeDeviceReq) (*RevokeDeviceResp, error)
	RevokeOtherDevices(context.Context, *RevokeOtherDevicesReq) (*RevokeOtherDevicesResp, error)
	RevokeAllDevices(context.Context, *RevokeAllDevicesReq) (*RevokeAllDevicesResp, error)
	// ── password_reset — request + apply (E1) ───────────────────
	// RequestPasswordReset (unauthenticated) mints + e-mails a reset token;
	// it ALWAYS returns success regardless of whether the email exists
	// (anti-enumeration). ResetPassword (unauthenticated) consumes the token,
	// sets the new password, and revokes every existing session. Gated
	// `password_reset`.
	RequestPasswordReset(context.Context, *RequestPasswordResetReq) (*RequestPasswordResetResp, error)
	ResetPassword(context.Context, *ResetPasswordReq) (*ResetPasswordResp, error)
	// ── email_verification — request + confirm (E1) ─────────────
	// RequestEmailVerification (bearer-authenticated — you verify your own
	// address) mints + e-mails a verification token. VerifyEmail
	// (unauthenticated — the link click carries no session) consumes the
	// token and stamps email_verified_at. Gated `email_verification`.
	RequestEmailVerification(context.Context, *RequestEmailVerificationReq) (*RequestEmailVerificationResp, error)
	VerifyEmail(context.Context, *VerifyEmailReq) (*VerifyEmailResp, error)
	// ── cli_login — first-party CLI OAuth (loopback + PKCE) ─────
	// CliAuthorize (bearer-authenticated — the user is signed into the web)
	// mints a single-use authorization code bound to the principal + the
	// CLI's PKCE challenge; the console web then redirects the browser to the
	// CLI's loopback redirect_uri?code=<code>. CliToken (unauthenticated —
	// the CLI has no token yet) verifies the PKCE verifier, consumes the
	// code, and mints the bearer the CLI stores. Gated `cli_login`. See
	// docs/specs/plugins/auth-cli-login-and-orgs.md.
	CliAuthorize(context.Context, *CliAuthorizeReq) (*CliAuthorizeResp, error)
	CliToken(context.Context, *CliTokenReq) (*CliTokenResp, error)
	// ── org_membership — list the caller's organizations ───────
	// ListMyOrgs returns the orgs the bearer-authenticated caller belongs to
	// (for the CLI's `org list` + the login-time membership cache + the init
	// org picker). The principal is the gateway-resolved caller (never a
	// client-sent user_id). Gated `org_membership`.
	ListMyOrgs(context.Context, *ListMyOrgsReq) (*ListMyOrgsResp, error)
	// ListOrgMembers — who is in the caller's active organization.
	ListOrgMembers(context.Context, *ListOrgMembersReq) (*ListOrgMembersResp, error)
	// ListAssignableRoles — the roles an invitation may name.
	//
	// Exists so a caller does not have to KNOW the vocabulary. The role on an
	// invitation is validated against the catalogue (roleIDByName), so a typo is
	// refused — but only after the invitation is submitted, and the refusal
	// cannot say what the valid answers were, because nothing on this surface
	// could enumerate them. A console UI had a free-text field for this and no
	// way to populate a picker (2026-09-11).
	//
	// Returns ORG-SCOPED roles only. A realm role is not something one member
	// hands another inside an organization — it is platform-wide, and offering
	// it here would put a realm grant behind an org admin's dropdown.
	//
	// Deliberately carries no permissions: the names and their descriptions are
	// what a human picks between, while which endpoints each one unlocks is an
	// implementation detail of the deployed lock that would go stale in a UI the
	// moment the surface grew.
	ListAssignableRoles(context.Context, *ListAssignableRolesReq) (*ListAssignableRolesResp, error)
	// InviteToOrg — invite an address into the active org with a role.
	InviteToOrg(context.Context, *InviteToOrgReq) (*InviteToOrgResp, error)
	// ListOrgInvites — the active org's outstanding invitations.
	ListOrgInvites(context.Context, *ListOrgInvitesReq) (*ListOrgInvitesResp, error)
	// RevokeOrgInvite — withdraw one of them.
	RevokeOrgInvite(context.Context, *RevokeOrgInviteReq) (*RevokeOrgInviteResp, error)
	// ListMyInvites — invitations addressed to the CALLER, in every org.
	// Not scoped to an active org, and could not be: the point is that the
	// caller is not a member of those organizations yet.
	ListMyInvites(context.Context, *ListMyInvitesReq) (*ListMyInvitesResp, error)
	// AcceptOrgInvite — join. One transaction: consume the invitation,
	// write the membership, and grant the role IN that organization.
	AcceptOrgInvite(context.Context, *AcceptOrgInviteReq) (*AcceptOrgInviteResp, error)
	// ChangePassword — rotate the caller's own password. Needs no mail
	// channel; the current password is the proof.
	ChangePassword(context.Context, *ChangePasswordReq) (*ChangePasswordResp, error)
}

